insert into school_private.arcade_bank(id,lesson,level,question)
select q->>'id',q->>'lesson',q->>'level',q from jsonb_array_elements($arcade$[{"id":"s1_u01_l01_q401","lesson":"s1_u01_l01","level":"easy","prompt":"في وصف حافة وادٍ، أي لفظ من مفردات سورة آل عمران يدل على الحافة؟","options":["شفا","بيّنات","نعمة","حبل"],"correct":0,"explanation":"الشفا حافة الشيء وطرفه.","pages":[7]},{"id":"s1_u01_l01_q402","lesson":"s1_u01_l01","level":"easy","prompt":"ورد في سورة آل عمران الأمر بالاعتصام بحبل الله. بمَ يكون هذا الاعتصام؟","options":["بترك التعاون عند الاختلاف","بالتمسّك بدين الله","بالتشبث بعادات الآباء كلها","بالانفراد عن جماعة المؤمنين"],"correct":1,"explanation":"فسّر جدول المفردات حبل الله بدينه، والاعتصام بالتمسّك.","pages":[7]},{"id":"s1_u01_l01_q403","lesson":"s1_u01_l01","level":"easy","prompt":"أي معنى تحمله كلمة «البيّنات» حين ترد في التحذير من الاختلاف بعد مجيئها؟","options":["الآراء المتعارضة","الحوادث المتوقعة","الدلائل الواضحة","العادات المألوفة"],"correct":2,"explanation":"البيّنات هي البراهين والدلائل الواضحة.","pages":[7]},{"id":"s1_u01_l01_q404","lesson":"s1_u01_l01","level":"easy","prompt":"بأي وصف تُصنّف سورة آل عمران من حيث زمن النزول؟","options":["مكية كلها","مكية عدا آية واحدة","لم يرد تصنيفها","مدنية"],"correct":3,"explanation":"يصف التعريف بالسورة آل عمران بأنها مدنية.","pages":[7]},{"id":"s1_u01_l01_q405","lesson":"s1_u01_l01","level":"easy","prompt":"أي سورتين ورد الحث على قراءتهما باسم «الزهراوين»؟","options":["البقرة وآل عمران","البقرة والنساء","آل عمران والمائدة","النساء والمائدة"],"correct":0,"explanation":"وردت البقرة وآل عمران في الحديث الذي أورده التعريف بالسورة.","pages":[7]},{"id":"s1_u01_l01_q406","lesson":"s1_u01_l01","level":"medium","prompt":"أدى بعض المسلمين صلاة الجنازة على متوفى، فكيف يؤثر ذلك في تكليف الآخرين بهذه الصلاة؟","options":["يلزم جميع الناس إعادتها","يسقط الطلب عن الباقين إذا قام بها من يكفي","تبقى واجبة على كل فرد بعينه","تصير واجبة على الأقارب وحدهم"],"correct":1,"explanation":"صلاة الجنازة مثال لفرض الكفاية.","pages":[9]},{"id":"s1_u01_l01_q407","lesson":"s1_u01_l01","level":"medium","prompt":"أدّى طالب صلاة الظهر، وظن زميله أن ذلك يُسقطها عنه. أي وصف لحكم الصلوات الخمس يصحح هذا الفهم؟","options":["نافلة لمن فاتته الجماعة","فرض يختص بمن يؤمّ الناس","فرض عين على كل مكلّف","فرض كفاية تؤديه الجماعة"],"correct":2,"explanation":"الصلوات الخمس من أمثلة فرض العين.","pages":[9]},{"id":"s1_u01_l01_q408","lesson":"s1_u01_l01","level":"medium","prompt":"يملك داعية علمًا بما يدعو إليه. أي أسلوب يوافق واجبه عند مخاطبة الناس؟","options":["يعنفهم ليضمن استجابتهم","يعرض عليهم ما لا يفهمونه عمدًا","يقيس نجاحه بمقدار الخوف منه","يبشّرهم ويخاطبهم بحكمة"],"correct":3,"explanation":"من شروط الدعوة الأسلوب الحكيم الذي يبشّر الناس ولا ينفّرهم.","pages":[9]},{"id":"s1_u01_l01_q409","lesson":"s1_u01_l01","level":"medium","prompt":"أراد طالب أن يرشد زملاءه إلى عمل خير، لكنه يجهل حكمه. ما الشرط الذي ينبغي أن يستكمله أولًا؟","options":["العلم بما يدعو إليه","كثرة عدد المستمعين","علو الصوت عند الحديث","انتماؤه إلى أسرة معروفة"],"correct":0,"explanation":"ذُكر العلم ضمن شروط مباشرة الدعوة إلى الخير.","pages":[9]},{"id":"s1_u01_l01_q410","lesson":"s1_u01_l01","level":"medium","prompt":"أيُّ تعبير يوافق مفهوم المنكر عند بيان وظيفة النهي عنه؟","options":["كل أمر يخالف المألوف","كل أمر مستقبح","كل أمر يجهله بعض الناس","كل أمر يصعب أداؤه"],"correct":1,"explanation":"يبيّن شرح الآية أن المنكر كل أمر مستقبح.","pages":[9]},{"id":"s1_u01_l01_q411","lesson":"s1_u01_l01","level":"hard","prompt":"بلدة تتوافر فيها القدرة على أداء فرض كفاية، فتَركه جميع أهلها اتكالًا بعضهم على بعض. ما النتيجة؟","options":["يتحول الفرض إلى نافلة","يؤجر الجميع على انتظار المبادرة","يأثم الجميع لعدم قيام من يكفي به","يسقط الطلب بتوزع المسؤولية"],"correct":2,"explanation":"فرض الكفاية إذا لم يقم به أحد أثم الجميع.","pages":[9]},{"id":"s1_u01_l01_q412","lesson":"s1_u01_l01","level":"hard","prompt":"يريد فريق أن يختار من يبين للناس وجه الخير. ما المعيار الذي يجمع شروط هذه المهمة؟","options":["الحماس وحده ولو نقص العلم","الشهرة ولو نفّر أسلوبه الناس","المعرفة دون قدرة على البيان","العلم والحكمة والقدرة على إيصال الرسالة"],"correct":3,"explanation":"تحتاج المهمة إلى العلم والأسلوب الحكيم والمهارة في إيصال الرسالة.","pages":[9]},{"id":"s1_u01_l01_q413","lesson":"s1_u01_l01","level":"hard","prompt":"أي حجة يردّ بها على من يقول إن مجرد وصول البراهين كافٍ لحماية الأمة من الضعف؟","options":["تنازعت أمم بعد مجيء البيّنات فضعفت","كل اختلاف يقع قبل ظهور الدليل","الأدلة تغني الأمم عن العمل","الضعف لا يتأثر بتنازع الناس"],"correct":0,"explanation":"ذكر الشرح أن الاختلاف بعد مجيء البراهين كان سببًا في الضعف.","pages":[9]},{"id":"s1_u01_l01_q414","lesson":"s1_u01_l01","level":"hard","prompt":"ما الدليل من موضوع الآية 103 من سورة آل عمران على أن للأمة أساسًا يجمع أفرادها؟","options":["ذكر وقت الصلوات الخمس","الأمر بالاعتصام بحبل الله جميعًا","تحديد عدد آيات السورة","بيان حكم صلاة الجنازة"],"correct":1,"explanation":"موضوع الآية التمسك بالإسلام أساس وحدة الأمة.","pages":[7]},{"id":"s1_u01_l01_q415","lesson":"s1_u01_l01","level":"hard","prompt":"استثار شخصٌ عداوة قديمة بين جماعتين بعد صلحهما. ما وجه الشبه بين عمله وفعل شاس بن قيس؟","options":["تعليم الناس حكم فرض الكفاية","تنظيم التعاون على الخير","محاولة تجديد النزاع بعد اجتماع القلوب","السعي إلى إصلاح ذات البين"],"correct":2,"explanation":"يذكر سبب النزول أنه استاء من اجتماع الأوس والخزرج وسعى إلى إثارة العداوة القديمة.","pages":[9]},{"id":"s1_u03_l04_q401","lesson":"s1_u03_l04","level":"medium","prompt":"أساء قوم إلى داعية، فاستبشر بإمكان هدايتهم ورفض الدعاء عليهم. أي موقف من السيرة يشبه تصرفه؟","options":["خروج النساء إلى مصلّى العيد","استئذان رجل في الخروج مع الجيش","سؤال الرجل عن أحق الناس بحسن صحابته","موقف النبي ﷺ بعد ما لقيه في الطائف"],"correct":3,"explanation":"بعد سوء معاملة أهل الطائف تفاءل النبي ﷺ بإسلامهم ورفض الدعاء عليهم.","pages":[97]},{"id":"s1_u03_l06_q401","lesson":"s1_u03_l06","level":"medium","prompt":"سُئل النبي ﷺ عن أحق الناس بحسن الصحبة، فأعاد ذكر الأم قبل أن يذكر الأب. كم مرة وردت الأم في جوابه؟","options":["ثلاث مرات","أربع مرات","مرة واحدة","مرتين"],"correct":0,"explanation":"ورد جواب «أمك» ثلاث مرات قبل «ثم أبوك» في الحديث الوارد في تكريم الأم.","pages":[106]},{"id":"u01_l01_q103","lesson":"u01_l01","level":"easy","prompt":"إلى أي أمر ترشد عبارة «سمعنا وأطعنا»؟","options":["الاكتفاء بالعلم دون عمل","الانقياد لأمر الله برضا","تقديم الرأي على الوحي","التردد في قبول التكليف"],"correct":1,"explanation":"يربط الدرس العبارة بالاستسلام لأوامر الله تعالى والعمل بمقتضاها.","pages":[10]},{"id":"u01_l01_q104","lesson":"u01_l01","level":"easy","prompt":"أي طلب من دعوات الآية (286) من سورة البقرة يعني ترك المعاقبة على الذنب؟","options":["النصر","الرزق","العفو","الهداية"],"correct":2,"explanation":"يميز شرح الدعاء بين طلب العفو وغيره ويجعله ترك المعاقبة على الذنب.","pages":[11]},{"id":"u01_l01_q105","lesson":"u01_l01","level":"medium","prompt":"لماذا يجمع دعاء طلب الرحمة بين العفو والمغفرة والإحسان؟","options":["لأنه يختص بأحداث الدنيا وحدها","لأنه يلغي مسؤولية الإنسان عن عمله","لأنه مقصور على دفع المشقة المالية","لأنه يتضمن التفضل على العبد بالنعم وعدم معاقبته"],"correct":3,"explanation":"يعرض شرح الصفحة 11 معنى الرحمة بوصفها أوسع من مجرد إسقاط العقوبة.","pages":[11]},{"id":"u01_l01_q106","lesson":"u01_l01","level":"medium","prompt":"ما الذي يجعل الاستغفار مناسبًا لحال المسلم حتى مع التزامه بطاعة الله؟","options":["تعرض الإنسان للخطأ والتقصير واحتياجه إلى المغفرة","انحصار الاستغفار في غير المؤمنين","انتفاء علاقة العمل بصدق الإيمان","امتناع الإنسان عن الوقوع في أي خطأ"],"correct":0,"explanation":"بين الكتاب أن الإنسان معرض للتقصير ولذلك يسارع إلى طلب المغفرة.","pages":[10]},{"id":"u01_l01_q109","lesson":"u01_l01","level":"hard","prompt":"طالب يخلط بين العفو والمغفرة؛ أي بيان يزيل الخلط؟","options":["المغفرة لا تتعلق بالذنوب والعفو لا يتعلق بالعقوبة","العفو ترك العقوبة والمغفرة طلب إسقاط الذنب","اللفظان يدلان في الكتاب على طلب العلم","العفو طلب الغلبة والمغفرة طلب الرزق"],"correct":1,"explanation":"يفصل شرح أدعية الآية بين ترك العقوبة وطلب المسامحة وإسقاط الذنب.","pages":[11]},{"id":"u01_l01_q114","lesson":"u01_l01","level":"medium","prompt":"أي حالة يذكرها الدرس مثالًا على الرخصة عند زيادة مشقة التكليف؟","options":["إلغاء الزكاة عن القادر","إسقاط الواجبات عن كل مسافر دائمًا","فطر المريض في رمضان","ترك الصلاة لمجرد الانشغال"],"correct":2,"explanation":"مثّل الكتاب لتخفيف المشقة بجواز الفطر للمريض والمسافر في رمضان.","pages":[10]},{"id":"u01_l01_q115","lesson":"u01_l01","level":"medium","prompt":"ما المبدأ المستفاد من أن الإنسان يحاسب على ما قدمه من خير أو شر؟","options":["تساوي النتائج مهما اختلف العمل","عدم الاعتداد بأفعال الناس","تحمل الإنسان أعمال الآخرين","مسؤولية الفرد عن عمله"],"correct":3,"explanation":"تشرح الآية (286) مسؤولية الإنسان عن عمله ضمن مبادئ الشريعة.","pages":[10]},{"id":"u01_l01_q116","lesson":"u01_l01","level":"medium","prompt":"لماذا تكرر نداء «ربنا» في أدعية الآية الأخيرة من سورة البقرة وفق الشرح؟","options":["لإظهار التذلل والإلحاح في طلب الاستجابة","للتقليل من أهمية الدعاء","للدلالة على استقلال الإنسان عن ربه","لإثبات أن الدعاء يغني عن الطاعة"],"correct":0,"explanation":"عدّ الكتاب تكرار النداء من آداب الدعاء الدالة على التذلل والرغبة والإلحاح.","pages":[11]},{"id":"u01_l01_q119","lesson":"u01_l01","level":"hard","prompt":"أي فهم يجمع بين مبدأ يسر الشريعة ووجود المشقة في أداء بعض العبادات؟","options":["سهولة الشريعة تعني عدم وجود جهد في أي عبادة","المشقة المحتملة قائمة لكن عند زيادتها شرعت رخص للتخفيف","وجود المشقة يمنع أي تيسير شرعي","كل مشقة مهما كانت تلغي أصل التكليف"],"correct":1,"explanation":"فرق الكتاب بين المشقة المعتادة التي يحتملها الإنسان والمشقة الزائدة التي تستدعي الرخصة.","pages":[10]},{"id":"u01_l01_q126","lesson":"u01_l01","level":"hard","prompt":"ما الموقف الذي يحقق معًا التصديق بالرسل والاستسلام لأمر الله بحسب الآية (285) من سورة البقرة؟","options":["الإيمان ببعض الرسل وترك بعضهم","إعلان الإيمان من غير أثر في العمل","الإيمان بجميع الرسل والعمل بمقتضى أوامر الله","اختيار ما يوافق الهوى من الرسالات"],"correct":2,"explanation":"يربط النص الإيمان بعدم التفريق بين الرسل وبالتسليم والطاعة.","pages":[10]},{"id":"u01_l01_q139","lesson":"u01_l01","level":"medium","prompt":"في دعاء «فانصرنا» في خاتمة سورة البقرة، على مَن طلب المؤمنون الغلبة؟","options":["أهل العلم في المناظرة","أفراد الأسرة عند الخلاف","كل من يختلف معهم في الرأي","الأعداء الظالمين المعتدين"],"correct":3,"explanation":"فسّر الدرس طلب النصر بأنه طلب الغلبة على الأعداء الظالمين المعتدين.","pages":[11]},{"id":"u01_l01_q147","lesson":"u01_l01","level":"medium","prompt":"أي دعاء في الآية (286) من سورة البقرة يتعلّق صراحةً بالتقصير الذي يقع بسبب السهو أو الخطأ؟","options":["طلب عدم المؤاخذة بالنسيان والخطأ","طلب الاستعانة في شؤون الحياة","طلب النصر على المعتدين","طلب زيادة الملك في الدنيا"],"correct":0,"explanation":"فرّق الدرس بين الطلب من الله عدم المؤاخذة بسبب النسيان والخطأ وسائر الأدعية.","pages":[11]},{"id":"s1_u01_l01_q033","lesson":"s1_u01_l01","level":"easy","prompt":"إلى أي قبيلة يُنسب شاس بن قيس في سبب نزول الآيات 102–105 من سورة آل عمران؟","options":["بني قريظة","بني قينقاع","بني النضير","بني المصطلق"],"correct":1,"explanation":"نسبه الكتاب إلى بني قينقاع.","pages":[9]},{"id":"s1_u01_l02_q002","lesson":"s1_u01_l02","level":"easy","prompt":"اجتناب الشبهات خوفًا من الوقوع في المحرمات، هذا مفهوم:","options":["الحلال الواضح","الحرام الواضح","الورع","المشتبهات"],"correct":2,"explanation":"الورع هو ترك ما اشتبه حكمه اتقاء الوقوع في الحرام.","pages":[13]},{"id":"s1_u01_l03_q002","lesson":"s1_u01_l03","level":"easy","prompt":"أن يقصد الإنسان بعبادته مدح الناس، هذا مفهوم:","options":["البدعة السيئة","النفاق الاعتقادي","الكفر الاعتقادي","الرياء"],"correct":3,"explanation":"يقصد المرائي بعبادته أن يمدحه الناس، وقد عُدّ الرياء من الشرك الأصغر.","pages":[22]},{"id":"s1_u01_l04_q001","lesson":"s1_u01_l04","level":"easy","prompt":"حق الفرد في أن تكون له قيمة وأن يحترم لذاته ويعامل بصورة لائقة، هذا مفهوم:","options":["الكرامة","المساواة","الأمن","الحرية"],"correct":0,"explanation":"ترتبط الكرامة باحترام الإنسان لذاته، بصرف النظر عن الاختلاف في الدين أو اللون أو العرق.","pages":[27]},{"id":"s1_u01_l06_q021","lesson":"s1_u01_l06","level":"easy","prompt":"في وصية النبي ﷺ بالنهي عن الغلول، ماذا يعني النهي «لا تغلوا»؟","options":["تعتدوا على النباتات","تأخذوا من الغنائم دون علم ولي الأمر","تسيئوا إلى غير المحاربين","تخالفوا العهود الموثقة"],"correct":1,"explanation":"فسّر الكتاب الغلول بهذا المعنى.","pages":[40]},{"id":"s1_u02_l01_q021","lesson":"s1_u02_l01","level":"easy","prompt":"من كلّفه أبو بكر بجمع القرآن الكريم؟","options":["أبو الأسود الدؤلي","أبو موسى الأشعري","زيد بن ثابت","حذيفة بن اليمان"],"correct":2,"explanation":"كلف أبو بكر زيد بن ثابت بهذه المهمة.","pages":[45]},{"id":"s1_u02_l02_q001","lesson":"s1_u02_l02","level":"easy","prompt":"أخذ المكلف بالأحكام الأصلية التي شرعها الله تشريعًا عامًا، هذا مفهوم:","options":["المشقة","العرف","الرخصة","العزيمة"],"correct":3,"explanation":"هذا تعريف العزيمة في الكتاب.","pages":[51]},{"id":"s1_u02_l03_q019","lesson":"s1_u02_l03","level":"easy","prompt":"من عينه النبي ﷺ أول قائد في جيش مؤتة؟","options":["زيد بن حارثة","عبد الله بن رواحة","جعفر بن أبي طالب","خالد بن الوليد"],"correct":0,"explanation":"ذكر الدرس تعيين زيد أولًا.","pages":[56]},{"id":"s1_u02_l05_q002","lesson":"s1_u02_l05","level":"easy","prompt":"إعطاء كل ذي حق حقه، هذا مفهوم:","options":["البر","العدالة","الكرامة","الحوار"],"correct":1,"explanation":"تتحقق العدالة بإعطاء المستحق حقه، وقد أمر الإسلام بالعدل حتى مع المخالف.","pages":[67]},{"id":"s1_u02_l06_q090","lesson":"s1_u02_l06","level":"easy","prompt":"أي مما يأتي من ضوابط عمل المرأة الواردة في المنهاج؟","options":["الحصول على الميراث","الحصول على النفقة","ألا يتسبب العمل في التقصير بالواجبات الأسرية","التملك والتصرف في الأموال"],"correct":2,"explanation":"من ضوابط العمل المذكورة الالتزام بالآداب الشرعية ومراعاة الواجبات الأسرية.","pages":[74]},{"id":"s1_u03_l02_q005","lesson":"s1_u03_l02","level":"medium","prompt":"إنفاق المال في المحرمات بصرف النظر عن مقداره، هذا مفهوم:","options":["الادخار","الاستثمار","الإسراف","التبذير"],"correct":3,"explanation":"هذا هو تعريف التبذير في الدرس.","pages":[86]},{"id":"s1_u03_l03_q066","lesson":"s1_u03_l03","level":"medium","prompt":"من رافق أبا سفيان إلى النبي ﷺ؟","options":["العباس","بلال بن رباح","أبو سفيان","عمرو بن سالم"],"correct":0,"explanation":"أخذه العباس إلى النبي ﷺ.","pages":[91]},{"id":"s1_u03_l05_q003","lesson":"s1_u03_l05","level":"easy","prompt":"من يتولى أمر المرأة في الزواج، هذا مفهوم:","options":["الشاهد","ولي المرأة","المأذون","الخاطب"],"correct":1,"explanation":"يعرف الكتاب ولي المرأة بهذا الوصف.","pages":[102]},{"id":"s1_u03_l06_q002","lesson":"s1_u03_l06","level":"easy","prompt":"أي أمٍّ من أمهات المؤمنين برزت في العلم وكانت مرجعًا للصحابة في معرفة أحكام الدين؟","options":["خديجة","أم سلمة","عائشة","حفصة"],"correct":2,"explanation":"أورد الدرس عائشة مثالًا للنساء اللواتي برزن في العلم.","pages":[107]},{"id":"s1_u04_l02_q064","lesson":"s1_u04_l02","level":"medium","prompt":"أي آية قرنت طاعة الرسول بطاعة الله؟","options":["النور 63","الحشر 7","النجم 3–4","النساء 80"],"correct":3,"explanation":"النساء 80 دليل ذلك.","pages":[118]},{"id":"s1_u04_l03_q001","lesson":"s1_u04_l03","level":"easy","prompt":"ما شاع بين الناس وتقبلوه من أقوال وأفعال لا تخالف الشريعة، هذا مفهوم:","options":["العرف","الإجماع","الرخصة","العرف الفاسد"],"correct":0,"explanation":"يورد الكتاب تعريف العرف بما لا يتعارض مع الشريعة.","pages":[125]},{"id":"s1_u04_l04_q002","lesson":"s1_u04_l04","level":"easy","prompt":"مال يدفعه الزوج لزوجته تكريمًا لها وتأكيدًا لرغبته في الزواج، هذا مفهوم:","options":["النفقة","المهر","الهبة المشترطة للأقارب","الميراث"],"correct":1,"explanation":"يورد الكتاب هذا التعريف للمهر.","pages":[132]},{"id":"s1_u04_l05_q001","lesson":"s1_u04_l05","level":"easy","prompt":"اتخاذ وسيلة مشروعة لإيجاد مدد زمنية متباعدة بين مرات الحمل، هذا مفهوم:","options":["الإجهاض","تحديد النسل","تنظيم النسل","الرعاية بعد الولادة"],"correct":2,"explanation":"عرف الدرس تنظيم النسل بالتباعد الزمني.","pages":[137]},{"id":"s1_u04_l06_q001","lesson":"s1_u04_l06","level":"easy","prompt":"توفير الغذاء الصحي الكافي لحاجات أفراد المجتمع في مختلف الظروف، هذا مفهوم:","options":["الأمن الاجتماعي","الرقابة على الأسواق","التكافل الاجتماعي","الأمن الغذائي"],"correct":3,"explanation":"هذا تعريف الأمن الغذائي في الدرس.","pages":[142]},{"id":"s1_u04_l07_q001","lesson":"s1_u04_l07","level":"easy","prompt":"تماسك أبناء الوطن وتحابهم وانتماؤهم إليه وتفانيهم في خدمته، هذا مفهوم:","options":["الوحدة الوطنية","الأمن الغذائي","المساواة وحدها","التعايش الدولي"],"correct":0,"explanation":"تظهر الوحدة الوطنية في انتماء أبناء الوطن وتماسكهم وتفانيهم في خدمته.","pages":[147]},{"id":"u01_l02_q195","lesson":"u01_l02","level":"medium","prompt":"\"أنَّ العقل السليم لا يقبل شيئًا من غير موجد له، ولا سببًا من غير مُسبب\"، هذا مفهوم:","options":["دليل الفطرة","دليل السببية","دليل الإتقان","دليل الهداية"],"correct":1,"explanation":"ورد في الكتاب أن دليل السببية يُقصد به أن العقل السليم لا يقبل شيئًا من غير موجد له، ولا سببًا من غير مسبب.","pages":[15]},{"id":"u01_l03_q229","lesson":"u01_l03","level":"easy","prompt":"ما الادعاء الذي أطلقه المشركون فجاء التحدي بالقرآن الكريم ردًا عليه؟","options":["ادّعوا أن المعجزات المادية هي وحدها دليل النبوة","ادّعوا أن القرآن الكريم نزل على الروم قبل العرب","ادّعوا أن القرآن الكريم ليس من عند الله تعالى، وإنما جاء به الرسول ﷺ من عنده","ادّعوا أن لغة القرآن غير مفهومة لقريش"],"correct":2,"explanation":"ورد في ص22: لما ادعى المشركون أن القرآن الكريم ليس من عند الله، وإنما جاء به الرسول ﷺ من عنده، تحداهم الله بمعجزة القرآن الكريم.","pages":[22]},{"id":"u01_l04_q196","lesson":"u01_l04","level":"medium","prompt":"\"البيان والتوضيح لطرائق الخير، والتحذير من طرائق الشر والتنفير منها بالحكمة والموعظة الحسنة\"، هذا مفهوم:","options":["تجنب التجسس","التغيير باليد","التغيير بالقلب","التغيير باللسان"],"correct":3,"explanation":"عرّف الكتاب في (الإثراء والتوسع) ص32 التغيير باللسان بأنه البيان والتوضيح لطرائق الخير والتحذير من طرائق الشر والتنفير منها بالحكمة والموعظة الحسنة.","pages":[32]},{"id":"u02_l01_q200","lesson":"u02_l01","level":"easy","prompt":"\"ما عَظُم قُبحه من الأفعال والأقوال، وما نشأ عنه ضرر وفساد كبير يطال الفرد والمجتمع، وقد توعد الله تعالى فاعلها بالعذاب الشديد فيما يُعرف بالكبائر\"، هذا مفهوم:","options":["الفواحش","الإثم","الكذب على الله","البغي"],"correct":0,"explanation":"هذا هو التعريف الصريح للفواحش كما ورد في المحور الثاني ص51.","pages":[51]},{"id":"u02_l03_q093","lesson":"u02_l03","level":"easy","prompt":"ما موضوع علم الجرح والتعديل؟","options":["حساب أنصبة الميراث","معرفة أحوال الرواة من حيث القبول والرد","ترتيب الآيات بحسب السور","تقسيم المصالح إلى أنواع"],"correct":1,"explanation":"عرف الدرس علم الجرح والتعديل بتقييم حال الرواة.","pages":[62]},{"id":"u02_l04_q202","lesson":"u02_l04","level":"easy","prompt":"\"صيام أكثر من يوم بتتابع دون إفطار\"، هذا مفهوم:","options":["التشدد في الصلاة","صيام الدهر","الوصال في الصوم","صيام التطوع"],"correct":2,"explanation":"عرّفت فقرة (الإثراء والتوسع) ص71 الوصال في الصوم بأنه صيام أكثر من يوم بتتابع دون إفطار.","pages":[71]},{"id":"u02_l06_q131","lesson":"u02_l06","level":"easy","prompt":"ما الوصف الزمني ليوم تبوك في سيرة النبي ﷺ؟","options":["الغزوة التي سبقت بدرًا","وقعة حدثت في السنة الثانية","أول غزوة بعد الهجرة","آخر غزوة غزاها النبي ﷺ"],"correct":3,"explanation":"يذكر الكتاب أن تبوك كانت آخر غزوة غزاها النبي ﷺ.","pages":[80]},{"id":"u02_l07_q112","lesson":"u02_l07","level":"easy","prompt":"أي صحابية أجارت زوجها أبا العاص فأقر النبي ﷺ إجارتها؟","options":["زينب بنت رسول الله ﷺ","أم عطية","أسماء بنت أبي بكر","أم سليم"],"correct":0,"explanation":"نص الكتاب على إقرار إجارة السيدة زينب لأبي العاص.","pages":[87]},{"id":"u03_l03_q191","lesson":"u03_l03","level":"easy","prompt":"\"مدة زمنية محددة من الشرع تنتظرها المرأة المطلقة أو الزوجة المتوفى عنها زوجها قبل أن يجوز لها الزواج من رجل آخر\"، هذا مفهوم:","options":["الإحداد","العدة","التعريض بالخطبة","الطلاق الرجعي"],"correct":1,"explanation":"هذا هو التعريف الصريح للعدة كما ورد في المحور الأول ص108.","pages":[108]},{"id":"u03_l04_q193","lesson":"u03_l04","level":"easy","prompt":"\"أن يتبرّع الإنسان بجزء من ماله أثناء حياته لشخص أو جهة ما؛ على أن يُنفَّذ هذا التبرّع بعد وفاته\"، هذا مفهوم:","options":["الوقف","الميراث","الوصية","الهبة الناجزة"],"correct":2,"explanation":"هذا هو التعريف الصريح للوصية كما ورد في المحور الأول ص115.","pages":[115]},{"id":"u03_l06_q196","lesson":"u03_l06","level":"easy","prompt":"\"سلوك يتسم بالغلو، ومجاوزة حد الاعتدال والتوسط، وهو من السلوكات التي تناقض الوسطية\"، هذا مفهوم:","options":["المرونة التشريعية","الاقتصاد في العبادة","التفريط","التطرف الفكري"],"correct":3,"explanation":"عرّفت فقرة (الإثراء والتوسع) ص130 التطرف الفكري بأنه سلوك يتسم بالغلو ومجاوزة حد الاعتدال والتوسط.","pages":[130]}]$arcade$::jsonb) q
on conflict(id) do update set lesson=excluded.lesson,level=excluded.level,question=excluded.question;
insert into school_private.arcade_bank(id,lesson,level,question)
select q->>'id',q->>'lesson',q->>'level',q from jsonb_array_elements($arcade$[{"id":"u03_l07_q193","lesson":"u03_l07","level":"easy","prompt":"\"وقف خيري يهدف إلى مكافحة الجوع ونقص التغذية بتوفيره وجبات غذائية متوازنة وصحية يوميًا\"، هذا مفهوم:","options":["وقف ثريد","وقفية مستشفى المقاصد","وقفية خير الأردن","وقفية التعليم"],"correct":0,"explanation":"ورد هذا التعريف الصريح لـ(وقف ثريد) في فقرة (أتوقف) ص136.","pages":[136]},{"id":"u04_l01_q200","lesson":"u04_l01","level":"medium","prompt":"\"الاعتداء على الأموال من دون وجه حق بأي صورة كانت، مثل السرقة والغش والاحتكار والرشوة ورفع الأسعار وعدم الوفاء بالدَّين\"، هذا مفهوم:","options":["سفك الدماء","أكل مال الناس بالباطل","الإيذاء المعنوي","الشتم والسباب"],"correct":1,"explanation":"هذا هو التعريف الصريح لأكل مال الناس بالباطل كما ورد ص142.","pages":[142]},{"id":"u04_l03_q220","lesson":"u04_l03","level":"easy","prompt":"ما العقوبة الشرعية إذا وقعت جريمة الاعتداء على النفس عن طريق (الخطأ) لا العمد؟","options":["لا عقوبة ولا دية مطلقًا","القِصاص بالقتل","الدِّيَة","ثمانون جلدة"],"correct":2,"explanation":"نص الكتاب ص155: «أما إذا وقعت جريمة الاعتداء على النفس عن طريق الخطأ فالعقوبة هي الدية».","pages":[155]},{"id":"u04_l06_q218","lesson":"u04_l06","level":"medium","prompt":"كيف طبّق النبي ﷺ عمليًا مبدأ المساواة بين الذكر والأنثى وتعميم (حق التعليم)؟","options":["اقتصر التعليم في عهده على المسجد النبوي للرجال فقط","منع تعليم القراءة والكتابة للقبائل خارج المدينة","فرض رسومًا مالية عالية على طلبة العلم","تخصيص أوقات لتعليم النساء وإرسال القرّاء إلى القبائل"],"correct":3,"explanation":"ذكرت ص176 أن النبي ﷺ ساوى بين الذكر والأنثى في التعليم؛ إذ خصّص أوقاتًا لتعليم النساء وأرسل القرّاء إلى القبائل يعلمون أبناءها القرآن وأحكام الدين.","pages":[176]},{"id":"u01_l05_q199","lesson":"u01_l05","level":"easy","prompt":"\"نفخة البعث؛ إذ يأمر الله تعالى الملك بالنفخ في الصور مَرَّة أُخرى، فيبعث الله تعالى الناس أحياءً من قبورهم\"، هذا مفهوم:","options":["النفخة الثانية","العرض","الحساب","النفخة الأولى"],"correct":0,"explanation":"عرّف الكتاب ص36 النفخة الثانية بأنها نفخة البعث التي يبعث الله فيها الناس أحياءً من قبورهم.","pages":[36]},{"id":"u03_l01_q208","lesson":"u03_l01","level":"easy","prompt":"\"كلُّ ما توعد الله تعالى فاعلها بالعذاب الشديد\"، هذا مفهوم:","options":["الزور فقط","الكبائر","اللغو","الإقتار"],"correct":1,"explanation":"ورد في ص95 تعريف الكبائر بأنها: كل ما توعد الله تعالى فاعلها بالعذاب الشديد.","pages":[95]},{"id":"u03_l01_q209","lesson":"u03_l01","level":"easy","prompt":"\"الشهادة الكاذبة التي يتوصل بها إلى الباطل، مثل أكل أموال الناس، وتضييع حقوقهم\"، هذا مفهوم:","options":["التقليد الأعمى","مجالس اللغو","شهادة الزور","البغي بغير الحق"],"correct":2,"explanation":"هذا هو التعريف الصريح لشهادة الزور كما ورد في الكتاب ص96.","pages":[96]},{"id":"s1_u01_l05_q014","lesson":"s1_u01_l05","level":"easy","prompt":"ما حكم الخطبة لمن أراد الزواج؟","options":["محرمة","واجبة","مكروهة","مندوبة"],"correct":3,"explanation":"ينص الدرس على أن الخطبة مندوبة لمن أراد الزواج.","pages":[34]},{"id":"s1_u03_l01_q091","lesson":"s1_u03_l01","level":"easy","prompt":"ما موضوع الآيات 169–171 من سورة آل عمران؟","options":["فضائل الشهداء","الثقة بنصر الله","نتائج الاستجابة","طاعة الله ورسوله"],"correct":0,"explanation":"خصصت الخريطة هذه الآيات لفضائل الشهداء.","pages":[78]},{"id":"u03_l02_q192","lesson":"u03_l02","level":"easy","prompt":"\"امتناع أحد الزوجين عن أداء واجباته تجاه الآخر، واستعلاؤه عليه\"، هذا مفهوم:","options":["الطلاق التعسفي","النشوز","الطلاق الكنائي","الإعراض المشروع"],"correct":1,"explanation":"ورد هذا التعريف الصريح للنشوز في التعلم القبلي ص100.","pages":[100]},{"id":"u04_l02_q195","lesson":"u04_l02","level":"medium","prompt":"\"الأخذ بما يليق بالإنسان من محاسن العادات، التي لا يُؤثر فقدها في حياة الإنسان، لكن وجودها يجعل للحياة بهجةً وجمالًا\"، هذا مفهوم:","options":["الضروريات","المصالح الملغاة","التحسينيات","الحاجيات"],"correct":2,"explanation":"هذا هو التعريف الصريح للتحسينيات كما ورد في فقرة (الإثراء والتوسع) ص150.","pages":[150]},{"id":"s1_u01_l05_q001","lesson":"s1_u01_l05","level":"easy","prompt":"عقد بين رجل وامرأة تحل له شرعًا لتكوين أسرة، هذا مفهوم:","options":["النفقة","الخطبة","المهر","الزواج"],"correct":3,"explanation":"أورد الكتاب هذا التعريف عن قانون الأحوال الشخصية الأردني.","pages":[32]},{"id":"u04_l04_q206","lesson":"u04_l04","level":"easy","prompt":"يُعدّ استهلال النبي ﷺ خطبته بقوله: «أَيُّهَا النَّاسُ» مثالًا على أسلوب:","options":["إثارة انتباه الناس باستخدام أسلوب النداء","توجيه السؤال والحوار","التشبيه لإيصال المقصود","الإيجاز والاختصار"],"correct":0,"explanation":"أورد البند (1) ص164 استهلال الخطبة بـ«أيها الناس» مثالًا على إثارة انتباه الناس باستخدام أسلوب النداء.","pages":[164]},{"id":"u04_l02_q102","lesson":"u04_l02","level":"easy","prompt":"أي مقصد يقع في مقدمة المقاصد الخمسة؟","options":["حفظ العقل","حفظ الدين","حفظ المال","حفظ النسل"],"correct":1,"explanation":"جعل الكتاب حفظ الدين في مقدمة المقاصد.","pages":[146]},{"id":"s1_u02_l04_q003","lesson":"s1_u02_l04","level":"easy","prompt":"ما الاسم الذي يُطلق على بنت الزوجة من زوج سابق؟","options":["الجدة","العمة","الربيبة","الحفيدة"],"correct":2,"explanation":"عرف الكتاب الربيبة بهذا الوصف.","pages":[62]},{"id":"s1_u02_l04_q020","lesson":"s1_u02_l04","level":"easy","prompt":"ما عدد أصناف المحرمات بسبب القرابة في تقسيم الكتاب؟","options":["خمسة","ثلاثة","ستة","أربعة"],"correct":3,"explanation":"عدد الكتاب أربعة أصناف.","pages":[61]},{"id":"s1_u04_l01_q004","lesson":"s1_u04_l01","level":"medium","prompt":"ما العلاقة التي تشير إليها الآية 21 بين الزوجين في سورة الروم؟","options":["المحبة والشفقة والتفاهم","التنافس في الحقوق دون تعاون","التفاهم مع غياب الرحمة","السكينة دون مراعاة المشاعر"],"correct":0,"explanation":"يشرح الكتاب المودة والرحمة بالمحبة والتفاهم والشفقة.","pages":[114]},{"id":"u03_l05_q131","lesson":"u03_l05","level":"easy","prompt":"أي سبب من أسباب الإرث يثبت بعقد زواج صحيح؟","options":["الجوار","الزوجية","الصداقة","العمل المشترك"],"correct":1,"explanation":"عدّ الدرس الزوجية القائمة على عقد صحيح سببًا للإرث.","pages":[120]},{"id":"u03_l05_q113","lesson":"u03_l05","level":"medium","prompt":"عند توزيع التركة، أيهما يُقدّم، سداد الدين أم تنفيذ الوصية؟","options":["تنفيذ الوصية مقدم دائمًا على الدين","يسقط الدين تلقائيًا عند الوفاة","سداد الدين مقدم على تنفيذ الوصية","يتصرف الوارث بحرية في تقديم أيهما"],"correct":2,"explanation":"ذكر صندوق التوقف أن الدين حق واجب ومقدم على تنفيذ الوصية.","pages":[121]},{"id":"u02_l05_q221","lesson":"u02_l05","level":"easy","prompt":"ما موقف المقوقس عظيم القبط في مصر بعد قراءة رسالة النبي ﷺ التي حملها حاطب بن أبي بلتعة رضي الله عنه؟","options":["قتل حامل الرسالة قبل وصوله","مزّق الرسالة وأساء معاملة حاطب بن أبي بلتعة","أعلن إسلامه وأرسل بذلك كتابًا إلى النبي ﷺ","قرأ الرسالة وأكرم حاملها وبعث معه بهدية إلى النبي ﷺ، لكنه لم يُسلم"],"correct":3,"explanation":"ورد في الفقرة (د) ص76 أن المقوقس قرأ الرسالة وأكرم حاملها وبعث معه بهدية إلى النبي ﷺ، لكنه لم يُسلم.","pages":[76]},{"id":"u02_l05_q224","lesson":"u02_l05","level":"hard","prompt":"كيف تجلّى كلٌّ من (تعظيم الله تعالى) و(تواضع النبي ﷺ) في صيغ رسائله إلى الملوك والزعماء؟","options":["تعظيم الله بالبدء بالبسملة، وتواضع النبي ﷺ بتضمين اسمه في الرسالة من دون أي ألقاب إلا لقب النبوة","تعظيم الله بذكر الأنبياء السابقين، وتواضع النبي ﷺ بترك ختم الرسائل","تعظيم الله بخاتم الذهب، وتواضع النبي ﷺ بذكر ألقاب الملوك كلها لنفسه","تعظيم الله بالآيات الطويلة، وتواضع النبي ﷺ بعدم ذكر اسمه في الرسالة"],"correct":0,"explanation":"ذكرت النقطة (3) ص76 اشتمال الرسائل على البدء بالبسملة تعظيمًا لله، وتضمين اسمه ﷺ من دون أية ألقاب إلا لقب النبوة تواضعًا.","pages":[76]},{"id":"u03_l02_q196","lesson":"u03_l02","level":"easy","prompt":"\"طلاق لا يستطيع الزوج بعده إعادة زوجته المطلقة إلى عصمته إلا برضاها، وبعقد ومهر جديدين\"، هذا مفهوم:","options":["الطلاق الرجعي","الطلاق البائن بينونة صغرى","الطلاق البائن بينونة كبرى","الطلاق التعسفي"],"correct":1,"explanation":"هذا هو التعريف الصريح للطلاق البائن بينونة صغرى كما ورد ص103.","pages":[103]},{"id":"u02_l05_q220","lesson":"u02_l05","level":"easy","prompt":"ما السبب الذي منع هرقل عظيم الروم من إعلان إسلامه رغم تأثره برسالة النبي ﷺ ومعرفته بشرفه وصدقه؟","options":["كذّب شهادة أبي سفيان في حق النبي ﷺ","لم يفهم لغة الرسالة العربية","خاف على ملكه، فلم يُسلم","لم يكن من أهل الكتاب"],"correct":2,"explanation":"نص الكتاب ص76 على أن هرقل تأثر بكتاب النبي ﷺ وعامل حامل الرسالة بالحسنى، لكنه خاف على ملكه فلم يُسلم.","pages":[76]},{"id":"u01_l06_q225","lesson":"u01_l06","level":"hard","prompt":"ما الشرط الذي وضعه العلماء لجواز التبرع بالأعضاء البشرية أثناء حياة المتبرع؟","options":["أن يكون المتبرع به عضوًا واحدًا فقط كالقلب","أن يكون المتبرع من كبار السن فوق الستين عامًا","أن يتقاضى المتبرع مقابلًا ماليًا لتعويض الضرر الصحي","ألّا يكون العضو الذي يُراد التبرع به من الأعضاء التي تعتمد عليها حياة المتبرع"],"correct":3,"explanation":"نص الكتاب ص44 على أن العلماء أجازوا التبرع أثناء حياة المتبرع بشرط ألّا يكون العضو من الأعضاء التي تعتمد عليها حياة المتبرع، مثل إحدى كليتيه.","pages":[44]},{"id":"u02_l02_arc1","lesson":"u02_l02","level":"easy","prompt":"ماذا يُقصد بالمصلحة في الشريعة الإسلامية؟","options":["جلب نفع للناس أو دفع ضرر عنهم","تحصيل الربح المالي وحده","تقديم المصلحة الخاصة دائمًا","اتباع كل ما تعارف عليه الناس"],"correct":0,"explanation":"يتناول مفهوم المصلحة ما ينفع الناس وما يدفع الضرر عنهم.","pages":[56]},{"id":"u02_l02_arc2","lesson":"u02_l02","level":"hard","prompt":"أُنشئت مؤسسة ترعى أموال الأيتام إلى أن يبلغوا سن الرشد. ما وجه اعتبارها مصلحة مرسلة؟","options":["تخص القائمين عليها بالنفع","تحفظ الأموال من غير نصّ خاص يقبل إنشاءها أو يرفضه","تُسقط حق اليتيم في ماله","تعارض نصًّا ثابتًا لتحقيق منفعة"],"correct":1,"explanation":"ذُكرت مؤسسة رعاية أموال الأيتام مثالًا على المصلحة المرسلة لما تحققه من حفظ حقوقهم.","pages":[57]},{"id":"u04_l05_arc1","lesson":"u04_l05","level":"easy","prompt":"ما المفهوم الذي يدل على التزام الفرد الأخلاقي تجاه مجتمعه للنهوض به وتحقيق مصالحه العامة؟","options":["الاستقلال الاقتصادي","التبادل التجاري","المسؤولية المجتمعية","الملكية الفردية"],"correct":2,"explanation":"يتحمل الفرد المسؤولية المجتمعية للنهوض بالمجتمع وتحقيق مصالحه العامة والحفاظ عليه.","pages":[167]},{"id":"u04_l05_arc2","lesson":"u04_l05","level":"medium","prompt":"نظّم فريق طلابي يومًا طبيًا مجانيًا للأسر المحتاجة. أي صورة من المسؤولية المجتمعية يطبقها؟","options":["الدفاع عن موارد المياه","رعاية مشروعات المبتكرين","تدريب الموظفين على التجارة","تقديم المساعدة للضعفاء والمحتاجين"],"correct":3,"explanation":"يعدّ تنظيم الأيام الطبية المجانية من أمثلة تقديم الرعاية الصحية للضعفاء والمحتاجين.","pages":[168]},{"id":"u04_l05_arc3","lesson":"u04_l05","level":"hard","prompt":"أراد فريق تمكين ذوي الإعاقة اقتصاديًا. أي مبادرة تحقق الغاية المذكورة في المنهاج بصورة مباشرة؟","options":["مساعدتهم على إقامة مشروعات تفي بحاجاتهم","تنظيم ندوة عامة عن حماية الماء","تحديد يوم لتوزيع كتب على المدارس","عقد لقاء عن تاريخ الجمعيات"],"correct":0,"explanation":"يرتبط التمكين بمساعدة ذوي الإعاقة على إقامة مشروعات تفي بحاجاتهم.","pages":[168]}]$arcade$::jsonb) q
on conflict(id) do update set lesson=excluded.lesson,level=excluded.level,question=excluded.question;
commit;
